// Shared course chrome; authored C readings and stable storage keys stay intact.
(()=>{
 const $=id=>document.getElementById(id),escape=text=>String(text).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const button=$('course-menu-button'),row=document.createElement('section');row.className='course-navigation';row.innerHTML='<div class="course-location"><span id="course-control-slot"></span><span id="course-row-progress"></span><nav id="course-breadcrumbs" aria-label="Breadcrumb"></nav></div><div id="course-contents" hidden></div>';document.querySelector('main').before(row);$('course-control-slot').append(button);button.innerHTML='Course lessons '+materialSymbol('expand_more');button.setAttribute('aria-controls','course-contents');
 const star=document.querySelector('.github-star');star.textContent='Source';document.querySelector('.copyright-notice').append(star);const brand=document.querySelector('.brand');brand.lastElementChild.textContent='C Foundry';brand.lastElementChild.insertAdjacentHTML('beforeend','<small>C17 programming</small>');
 const labGroups=COURSE.parts.map((name,i)=>({id:String(i+1),number:i+1,title:name,href:'#/lab/'+(i+1),summary:['Write C programs using values, branches, loops, functions, arrays and strings.','Use pointers, manage allocated memory, structure data and work with files.','Measure algorithmic cost and implement searching, sorting and recursion.','Build lists, queues, hash tables, trees, heaps and graphs.','Define tables, parse commands, execute queries and save records.','Organise pages and indexes, plan queries and test recovery.','Make C programs and stored formats portable across compilers and platforms.','Coordinate threads with locks, condition variables and atomic operations.','Manage multiple clients, isolation, snapshots, queries and storage maintenance.'][i],requirement:i?'Builds on '+COURSE.parts[i-1]+'.':'No previous programming experience required.',lessons:COURSE.chapters.filter(c=>c.part===i&&c.status==='ready').flatMap(c=>c.topics.map(t=>({id:c.id+'/'+t.id,title:t.title,href:'#/chapter/'+c.id+'/'+t.id})))}));
 const done=id=>lessonCompletion.isDone(id);let savedLast;const last=()=>{try{return localStorage.getItem('c-foundry:hub:last-lesson')||savedLast}catch{return savedLast}};
 function remember(id){savedLast=id;try{localStorage.setItem('c-foundry:hub:last-lesson',id)}catch{}}
 const initialResume=$('course-start-link').getAttribute('href'),initialContinue=$('course-start-link').textContent.includes('Continue');
 const cover=$('curriculum-view').querySelector('.course-cover'),choices=$('curriculum-view').querySelector('.course-outline'),art=cover.querySelector('figure');choices.innerHTML='<div class="hub-heading"><h2 id="course-outline-title" tabindex="-1">Choose a lab</h2><p id="hub-count"></p></div><div class="foundry-lab-grid" id="course-cards"></div>';
 const labPage=document.createElement('section');labPage.id='foundry-lab-page';$('curriculum-view').append(labPage);art.classList.add('hub-art');
 function arrange(){if(matchMedia('(max-width:900px)').matches)choices.after(art);else cover.append(art);}matchMedia('(max-width:900px)').addEventListener('change',arrange);arrange();
 function hub(){const {parts}=route(),group=parts[0]==='lab'?labGroups.find(g=>g.id===parts[1]):null,isHub=parts[0]==='course';cover.hidden=!isHub;choices.hidden=!isHub;art.hidden=!isHub;labPage.hidden=!group;
  if(group){labPage.innerHTML=foundryHub.overview(group,done,last(),'#/course');document.title=group.title+' · C Foundry';}
  if(isHub){$('course-cards').className='foundry-lab-grid';$('course-cards').innerHTML=foundryHub.cards(labGroups,done);$('hub-count').textContent=labGroups.filter(g=>g.lessons.every(l=>done(l.id))).length+' / '+labGroups.length+' labs complete';const target=foundryHub.destination(labGroups.flatMap(g=>g.lessons),done,last());const legacy=!last()&&initialContinue&&initialResume?.startsWith('#/lesson/');$('course-start-link').href=legacy?initialResume:target.lesson.href;$('course-start-link').textContent=legacy?'Continue your saved exercise →':target.label+': '+target.lesson.title;$('course-start-context').textContent='Choose a focused lab below, or open your next lesson directly.';document.title='C Foundry · Learn C';}
 }
 window.refreshFoundryHub=hub;
 let selectedPart;
 function route(){const parts=location.hash.slice(2).split('/');const chapter=parts[0]==='chapter'?COURSE.chapters.find(c=>c.id===parts[1]):parts[0]==='lesson'?COURSE.chapters.find(c=>c.labs.includes(parts[1])):null;return {parts,chapter,topic:chapter?.topics.find(t=>t.id===parts[2])};}
 function close(){button.setAttribute('aria-expanded','false');$('course-contents').hidden=true;}
 function outline(){const current=route(),part=selectedPart??current.chapter?.part??0;const scoped=current.chapter?labGroups[current.chapter.part].lessons:labGroups.flatMap(g=>g.lessons);$('course-row-progress').textContent=`${scoped.filter(l=>done(l.id)).length} / ${scoped.length} complete`;
  $('course-contents').innerHTML=`<a href="${current.chapter?labGroups[current.chapter.part].href:'#/course'}">${current.chapter?'Lab overview':'All labs'}</a><details class="outline-workspaces"><summary>Independent workspaces</summary><p><a href="#/workspace">Command workspace</a> keeps files for independent C programs. <a href="#/linux">Browser Linux</a> provides the optional terminal and native tools.</p></details><label for="outline-part">Course part</label><select id="outline-part">${COURSE.parts.map((name,i)=>`<option value="${i}" ${part===i?'selected':''}>${i+1}. ${escape(name)}</option>`).join('')}</select><div class="course-outline-grid">${COURSE.chapters.filter(c=>c.part===part).map(c=>`<section><h3><a href="#/chapter/${c.id}">${c.number}. ${escape(c.title)}</a></h3><ol>${c.topics.map(t=>{const id=c.id+'/'+t.id;return `<li><a href="#/chapter/${id}" ${location.hash==='#/chapter/'+id?'aria-current="page"':''}>${lessonCompletion.isDone(id)?materialSymbol('check'):''}<span>${escape(t.title)}</span></a></li>`;}).join('')}</ol></section>`).join('')}</div>`;
  $('outline-part').onchange=event=>{selectedPart=Number(event.target.value);outline();};
 }
 button.onclick=()=>{const opening=$('course-contents').hidden;button.setAttribute('aria-expanded',String(opening));$('course-contents').hidden=!opening;if(opening)outline();};
 row.addEventListener('keydown',event=>{if(event.key==='Escape'){event.preventDefault();close();button.focus();}});
 function destination(href){const parts=(href||'').replace(/^#\//,'').split('/');if(parts[0]==='chapter'){const c=COURSE.chapters.find(c=>c.id===parts[1]),t=c?.topics.find(t=>t.id===parts[2]);return t?.title||c?.title||'Course overview';}if(parts[0]==='lesson')return LESSONS.find(l=>l.id===parts[1])?.title||'Practice';return {'course':'Choose a lesson','workspace':'C workspace','linux':'Browser Linux'}[parts[0]]||'Course overview';}
 function resources(){for(const details of document.querySelectorAll('main .lesson-references')){
   const summary=details.querySelector(':scope > summary');const names=[...details.querySelectorAll(':scope > ul > li > a')].map(a=>a.textContent.replace('(new tab)','').trim());summary.innerHTML=materialSymbol('menu_book')+`<span><strong>References</strong><small>${escape(names.join(' · '))}</small></span>`+materialSymbol('chevron_right');details.classList.add('resource-row');
   const practice=details.parentElement.querySelector('.documentation-practice');if(practice){const section=document.createElement('section');section.className='documentation-practice';section.innerHTML='<h3>Try the documentation</h3>'+[...practice.children].filter(el=>el.tagName!=='SUMMARY').map(el=>el.outerHTML).join('');const consult=section.querySelector('p a');if(consult)consult.parentElement.textContent='Use the '+consult.textContent.replace('(new tab)','').trim()+' link above, then open Compare your answer.';details.append(section);practice.remove();}
  }}
 function prediction(){const host=document.querySelector('#inline-editor-host');if(!host)return;const id=location.hash;host.insertAdjacentHTML('beforebegin','<label class="prediction-label" for="course-prediction">Your prediction (optional)</label><textarea id="course-prediction" rows="2" placeholder="What do you expect the program to show?"></textarea>');const field=$('course-prediction');field.value=window.cFoundryApp.prediction(id);field.oninput=()=>window.cFoundryApp.savePrediction(id,field.value);}
 function render(){close();selectedPart=undefined;const {chapter,topic,parts}=route();hub();const group=chapter?labGroups[chapter.part]:parts[0]==='lab'?labGroups.find(g=>g.id===parts[1]):null;brand.href=group?group.href:'#/course';brand.querySelector('small').textContent=group?group.title:'C17 programming';row.hidden=['course','lab'].includes(parts[0]);if(chapter&&topic)remember(chapter.id+'/'+topic.id);$('course-breadcrumbs').innerHTML=chapter?`<span aria-hidden="true">/</span><a href="#/chapter/${chapter.id}">${escape(chapter.title)}</a>${topic?`<span aria-hidden="true">/</span><span aria-current="page">${escape(topic.title)}</span>`:''}`:`<span aria-hidden="true">/</span><span aria-current="page">${escape(document.querySelector('main>section:not([hidden]) h1')?.textContent||'Course')}</span>`;
  outline();document.querySelector('main .reading-breadcrumb')?.remove();document.querySelector('main .chapter-controls')?.remove();resources();prediction();
  for(const label of document.querySelectorAll('.completion-control')){const text=[...label.childNodes].find(n=>n.nodeType===Node.TEXT_NODE);if(text)text.textContent=' Mark lesson complete';}
  for(const nav of document.querySelectorAll('main .page-navigation')){const links=[...nav.querySelectorAll('a')];if(parts[1]==='first-program'&&parts[2]==='1'&&links[0])links[0].setAttribute('href','#/course');links.forEach((link,i)=>{const href=link.getAttribute('href'),title=destination(href),old=link.textContent,label=href==='#/course'?'Course overview':/Start/.test(old)?'Start chapter':/^#\/chapter\/[^/]+$/.test(href)?(/Previous/.test(old)?'Previous chapter':'Chapter overview'):/Previous/.test(old)?'Previous lesson':'Next lesson';link.innerHTML=`<small>${label}</small><strong>${escape(title)}</strong>`;});}
  if(chapter){const group=labGroups[chapter.part];for(const link of document.querySelectorAll('main .page-navigation a')){const match=link.hash.match(/^#\/chapter\/([^/]+)/);const destination=match&&COURSE.chapters.find(c=>c.id===match[1]);if((destination&&destination.part!==chapter.part)||(!destination&&link.hash==='#/course')){link.href=group.href;link.innerHTML='<small>Lab overview</small><strong>'+escape(group.title)+'</strong>';}}}
  // Local source/fixture links follow the current document's immutable release.
  const id=document.querySelector('meta[name="gpu-release"]')?.content;if(id){const base=new URL(document.querySelector('meta[name="gpu-base"]').content,location.href);for(const el of document.querySelectorAll('main a[href]')){const href=el.getAttribute('href');if(!/^(?:#|[a-z]+:|\/)/.test(href))el.href=new URL(`releases/${id}/`+href.replace(/^\.\//,''),base);}}
 }
 addEventListener('c-foundry:route',render);addEventListener('lessoncompletionchange',outline);render();
})();
